//! Release as policy synthesis (work order FERROPLAN-26922-09, composition
//! C01): the v26.9.22 Semantic-Jira work graph compiled into an HDDL/FOND
//! domain+problem and solved by [`ferroplan::hddl::solve_hddl`] for a
//! strong-cyclic policy.
//!
//! The fixture under [`fixtures/sjira-release-policy/`] is GENERATED by
//! `scripts/gen_sjira_release_policy.py` from `/Users/sac/wt/v26922/orders.json`
//! (projected into the committed `work-graph.json`; `--check` re-renders the
//! HDDL from it and fails on drift). Every order is a task whose `execute`
//! action has the nondeterministic court outcomes `oneof {alive, refuted,
//! blocked}`; refuted routes to `repair`, blocked to `defer`, both back to a
//! re-run, so the policy is strong-cyclic (fairness-dependent), never strong.
//!
//! Asserted here, all against the real pipeline (parse -> ground -> translate
//! -> FOND fixpoint) and the independent validator:
//!
//! 1. the fixture is exactly the projection of `work-graph.json` (sweep visit
//!    order, pending/goal facts, `depends-on` facts), so the graph the
//!    assertions read is the graph the planner solved;
//! 2. every (order x outcome) pair is reachable under the policy and each
//!    refuted/blocked outcome is followed by that order's repair/defer;
//! 3. no `execute` is chosen in a state where one of the order's
//!    dependencies (read from `work-graph.json`, not the domain) is not alive;
//! 4. `validate_fond_policy` classifies the policy `StrongCyclic`;
//! 5. falsifier: deleting one binding `depends-on` edge from the fixture
//!    changes the policy's schedule (the freed order now runs before its
//!    former dependency), while deleting a non-binding edge does not -- so
//!    the schedule comparison discriminates rather than always differing.

use ferroplan::hddl::{adapt_problem, solve_hddl};
use ferroplan::planning_runtime::{PlannerLimits, PolicyEntry, UniversalPlan};
use ferroplan::planning_types::PlanningType;
use ferroplan::policy_validation::{validate_fond_policy, PolicyGuarantee};
use ferroplan_hddl::translate::PlanningProblem as FlatProblem;
use std::collections::{BTreeMap, BTreeSet, VecDeque};
use std::time::{Duration, Instant};

const DOMAIN: &str = include_str!("fixtures/sjira-release-policy/domain.hddl");
const PROBLEM: &str = include_str!("fixtures/sjira-release-policy/problem.hddl");
const WORK_GRAPH: &str = include_str!("fixtures/sjira-release-policy/work-graph.json");

/// Wall budget per `solve_hddl` call (no-hang contract; the solve itself is
/// far below it).
const WALL_BUDGET_MS: u64 = 300_000;

/// The court outcomes of one order's `execute` action.
const OUTCOMES: [&str; 3] = ["alive", "refuted", "blocked"];

fn limits() -> PlannerLimits {
    PlannerLimits {
        max_wall_ms: WALL_BUDGET_MS,
        ..PlannerLimits::default()
    }
}

/// `work-graph.json`: order (HDDL name, lowercased id) -> its dependencies.
fn work_graph() -> BTreeMap<String, BTreeSet<String>> {
    let doc: serde_json::Value = serde_json::from_str(WORK_GRAPH).expect("work-graph.json parses");
    doc["orders"]
        .as_array()
        .expect("work-graph.json has an orders array")
        .iter()
        .map(|o| {
            let id = o["id"].as_str().expect("order id").to_lowercase();
            let deps = o["deps"]
                .as_array()
                .expect("order deps")
                .iter()
                .map(|d| d.as_str().expect("dep id").to_lowercase())
                .collect();
            (id, deps)
        })
        .collect()
}

/// The `(depends-on <order> <dependency>)` init facts of a problem text,
/// read line by line exactly as the generator emits them.
fn depends_on_facts(problem: &str) -> BTreeMap<String, BTreeSet<String>> {
    let mut edges = BTreeMap::<String, BTreeSet<String>>::new();
    for line in problem.lines() {
        if let Some(rest) = line.trim().strip_prefix("(depends-on ") {
            let mut parts = rest.trim_end_matches(')').split_whitespace();
            let (Some(o), Some(d), None) = (parts.next(), parts.next(), parts.next()) else {
                panic!("malformed depends-on line: {line}");
            };
            edges.entry(o.to_owned()).or_default().insert(d.to_owned());
        }
    }
    edges
}

/// Deletes exactly one `(depends-on o d)` line from the problem text.
fn drop_edge(problem: &str, order: &str, dep: &str) -> String {
    let needle = format!("(depends-on {order} {dep})");
    let kept: Vec<&str> = problem.lines().filter(|l| l.trim() != needle).collect();
    assert_eq!(
        kept.len() + 1,
        problem.lines().count(),
        "the edge {needle} must occur on exactly one fixture line"
    );
    kept.join("\n") + "\n"
}

/// The sweep's visit order: the `(visit <order>)` subtasks of the domain's
/// generated chunk methods, in declaration order.
fn visit_order(domain: &str) -> Vec<String> {
    domain
        .lines()
        .filter_map(|l| l.trim().strip_suffix("))"))
        .filter_map(|l| l.split_once(" (visit ").map(|(_, o)| o.to_owned()))
        .collect()
}

/// Rebuilds the explicit composite-state space `solve_hddl` solved over, via
/// the same public `ferroplan_hddl` pipeline, so policy outcomes can be read
/// as fact sets (`UniversalPlan` carries only state ids).
fn flat_problem(domain: &str, problem: &str) -> FlatProblem {
    let domain = ferroplan_hddl::parser::parse_domain(domain).expect("fixture domain parses");
    let problem = ferroplan_hddl::parser::parse_problem(problem).expect("fixture problem parses");
    let ir = ferroplan_hddl::grounder::ground(&domain, &problem, &Default::default())
        .expect("fixture grounds");
    let limits = ferroplan_hddl::translate::TranslateLimits {
        max_wall: Some(Duration::from_millis(WALL_BUDGET_MS)),
        ..Default::default()
    };
    ferroplan_hddl::translate::translate(&ir, &limits).expect("fixture translates")
}

/// A solved fixture: the policy, the explicit composite-state space it is
/// defined over, and the reachable policy graph.
struct Solved {
    plan: UniversalPlan,
    flat: FlatProblem,
    by_state: BTreeMap<String, PolicyEntry>,
    facts: BTreeMap<String, BTreeSet<String>>,
    /// States reachable from the initial state following every outcome of
    /// every chosen action.
    reached: BTreeSet<String>,
}

fn solve(problem: &str) -> Solved {
    let start = Instant::now();
    let plan = solve_hddl(DOMAIN, problem, &limits()).expect("release graph must solve");
    let elapsed = start.elapsed().as_millis();
    assert!(
        elapsed < u128::from(WALL_BUDGET_MS),
        "no-hang contract: solve took {elapsed}ms (budget {WALL_BUDGET_MS}ms)"
    );
    assert!(plan.solved, "expected plan.solved");
    assert!(
        matches!(plan.planning_type, Some(PlanningType::Fond)),
        "solve_hddl must report PlanningType::Fond, got {:?}",
        plan.planning_type
    );
    let flat = flat_problem(DOMAIN, problem);
    assert_eq!(
        flat.initial_states.len(),
        1,
        "one root network, one initial state"
    );
    let facts: BTreeMap<String, BTreeSet<String>> = flat
        .states
        .iter()
        .map(|s| (s.id.clone(), s.facts.clone()))
        .collect();
    let by_state: BTreeMap<String, PolicyEntry> = plan
        .policy
        .iter()
        .map(|e| (e.state.clone(), e.clone()))
        .collect();
    let mut reached = BTreeSet::new();
    let mut queue = VecDeque::from([flat.initial_states[0].clone()]);
    while let Some(state) = queue.pop_front() {
        if !reached.insert(state.clone()) {
            continue;
        }
        let state_facts = facts
            .get(&state)
            .unwrap_or_else(|| panic!("policy outcome names unknown state '{state}'"));
        if flat.goal.facts.is_subset(state_facts) {
            continue;
        }
        let entry = by_state
            .get(&state)
            .unwrap_or_else(|| panic!("reachable non-goal state '{state}' has no policy entry"));
        assert!(
            !entry.outcomes.is_empty(),
            "entry at '{state}' has no outcomes"
        );
        for outcome in &entry.outcomes {
            queue.push_back(outcome.state.clone());
        }
    }
    Solved {
        plan,
        flat,
        by_state,
        facts,
        reached,
    }
}

/// `htn:exec:<addr>:execute(o)` -> `Some(("execute", "o"))`; decomposition
/// transitions (`htn:decompose:...`) -> `None`.
fn primitive(action: &str) -> Option<(&str, &str)> {
    let rest = action.strip_prefix("htn:exec:")?;
    let call = rest.rsplit(':').next()?;
    let (name, args) = call.split_once('(')?;
    Some((name, args.strip_suffix(')')?))
}

fn fact(pred: &str, order: &str) -> String {
    format!("{pred}({order})")
}

impl Solved {
    /// The reachable policy entries choosing a primitive action.
    fn primitive_entries(&self) -> impl Iterator<Item = (&PolicyEntry, &str, &str)> {
        self.reached
            .iter()
            .filter_map(|s| self.by_state.get(s))
            .filter_map(|e| primitive(&e.action).map(|(name, arg)| (e, name, arg)))
    }

    /// The nominal schedule: follow the policy from the initial state, taking
    /// each `execute`'s alive outcome, and record the order executed.
    fn schedule(&self) -> Vec<String> {
        let mut schedule = Vec::new();
        let mut state = self.flat.initial_states[0].clone();
        for _ in 0..self.facts.len() {
            if self.flat.goal.facts.is_subset(&self.facts[&state]) {
                return schedule;
            }
            let entry = &self.by_state[&state];
            state = match primitive(&entry.action) {
                Some(("execute", order)) => {
                    schedule.push(order.to_owned());
                    let alive = fact("alive", order);
                    entry
                        .outcomes
                        .iter()
                        .find(|o| self.facts[&o.state].contains(&alive))
                        .expect("execute has an alive outcome")
                        .state
                        .clone()
                }
                _ => {
                    assert_eq!(
                        entry.outcomes.len(),
                        1,
                        "only execute is nondeterministic: {}",
                        entry.action
                    );
                    entry.outcomes[0].state.clone()
                }
            };
        }
        panic!("nominal path did not reach the goal within the state count");
    }
}

fn position(schedule: &[String], order: &str) -> usize {
    schedule
        .iter()
        .position(|o| o == order)
        .unwrap_or_else(|| panic!("{order} missing from schedule"))
}

#[test]
fn fixture_is_the_projection_of_the_work_graph() {
    let graph = work_graph();
    let doc: serde_json::Value = serde_json::from_str(WORK_GRAPH).expect("work-graph.json parses");
    assert!(graph.len() > 100, "the v26.9.22 graph has >100 orders");
    let edges = depends_on_facts(PROBLEM);
    let graph_edges: BTreeMap<String, BTreeSet<String>> = graph
        .iter()
        .filter(|(_, deps)| !deps.is_empty())
        .map(|(o, deps)| (o.clone(), deps.clone()))
        .collect();
    assert_eq!(edges, graph_edges, "depends-on facts == work-graph edges");
    // One sweep visits every order exactly once, in `050_frontier.rq`'s
    // `ORDER BY ?id` order over the ORIGINAL ids (`ASHATL-` < `ASH_A2A-`
    // there, although the lowercased HDDL names sort the other way).
    let ids: Vec<&str> = doc["orders"]
        .as_array()
        .expect("orders array")
        .iter()
        .map(|o| o["id"].as_str().expect("order id"))
        .collect();
    assert!(
        ids.windows(2).all(|w| w[0] < w[1]),
        "work-graph.json sorted by id"
    );
    let expected: Vec<String> = ids.iter().map(|id| id.to_lowercase()).collect();
    assert_eq!(visit_order(DOMAIN), expected);
    for order in graph.keys() {
        assert!(PROBLEM.contains(&format!("(pending {order})")));
        assert!(PROBLEM.contains(&format!("(alive {order})")));
    }
    let source_sha = doc["source"]["sha256"].as_str().expect("source sha256");
    for text in [DOMAIN, PROBLEM] {
        assert!(
            text.starts_with(";; GENERATED by scripts/gen_sjira_release_policy.py")
                && text.contains(source_sha),
            "fixture header must bind it to work-graph.json's source sha256"
        );
    }
}

#[test]
fn release_policy_covers_every_outcome_respects_dependencies_and_is_strong_cyclic() {
    let graph = work_graph();
    let solved = solve(PROBLEM);

    // (4) independent validation: strong-cyclic, not strong (retry loops).
    let report = validate_fond_policy(&adapt_problem(solved.flat.clone()), &solved.plan);
    assert!(
        report.issues.is_empty(),
        "validator issues: {:?}",
        report.issues
    );
    assert!(report.valid);
    assert_eq!(report.guarantee, PolicyGuarantee::StrongCyclic);

    // (2) every (order x outcome) pair is reachable, and recovery follows.
    let mut covered = BTreeSet::<(String, &str)>::new();
    let mut repaired = BTreeSet::<String>::new();
    let mut deferred = BTreeSet::<String>::new();
    for (entry, name, order) in solved.primitive_entries() {
        let state_facts = &solved.facts[&entry.state];
        match name {
            "execute" => {
                // (3) no action precedes a dependency.
                for dep in &graph[order] {
                    assert!(
                        state_facts.contains(&fact("alive", dep)),
                        "execute({order}) chosen before its dependency {dep} is alive"
                    );
                }
                assert_eq!(
                    entry.outcomes.len(),
                    3,
                    "execute({order}) keeps all 3 outcomes"
                );
                for outcome in &entry.outcomes {
                    assert!(solved.reached.contains(&outcome.state));
                    let target = &solved.facts[&outcome.state];
                    let hits: Vec<&str> = OUTCOMES
                        .into_iter()
                        .filter(|o| target.contains(&fact(o, order)))
                        .collect();
                    assert_eq!(
                        hits.len(),
                        1,
                        "execute({order}) outcome is one court verdict"
                    );
                    covered.insert((order.to_owned(), hits[0]));
                }
            }
            "repair" => {
                assert!(state_facts.contains(&fact("refuted", order)));
                repaired.insert(order.to_owned());
            }
            "defer" => {
                assert!(state_facts.contains(&fact("blocked", order)));
                deferred.insert(order.to_owned());
            }
            other => panic!("unexpected primitive action {other}({order})"),
        }
    }
    for order in graph.keys() {
        for outcome in OUTCOMES {
            assert!(
                covered.contains(&(order.clone(), outcome)),
                "({order} x {outcome}) not covered by the policy"
            );
        }
    }
    let orders: BTreeSet<String> = graph.keys().cloned().collect();
    assert_eq!(repaired, orders, "every refuted order is repaired");
    assert_eq!(deferred, orders, "every blocked order is deferred");

    // The nominal schedule runs every order exactly once, dependencies first.
    let schedule = solved.schedule();
    assert_eq!(schedule.len(), graph.len());
    assert_eq!(schedule.iter().cloned().collect::<BTreeSet<_>>(), orders);
    for (order, deps) in &graph {
        for dep in deps {
            assert!(position(&schedule, dep) < position(&schedule, order));
        }
    }
}

#[test]
fn removing_one_dependency_edge_changes_the_policy() {
    let graph = work_graph();
    let visits = visit_order(DOMAIN);
    let rank = |o: &str| visits.iter().position(|v| v == o).expect("order visited");

    // Binding edge: o's only dependency d sorts after o, so o cannot run in
    // the sweep that visits it before d; freed of the edge it runs before d.
    let (o, d) = graph
        .iter()
        .find_map(
            |(o, deps)| match deps.iter().collect::<Vec<_>>().as_slice() {
                [d] if rank(d) > rank(o) => Some((o.clone(), (*d).clone())),
                _ => None,
            },
        )
        .expect("the graph has a single-dependency descent edge");
    // Non-binding edge: o2's only dependency d2 is a root sorting before o2,
    // so d2 is alive by the time the first sweep visits o2 either way.
    let (o2, d2) = graph
        .iter()
        .find_map(
            |(o, deps)| match deps.iter().collect::<Vec<_>>().as_slice() {
                [d] if rank(d) < rank(o) && graph[*d].is_empty() => Some((o.clone(), (*d).clone())),
                _ => None,
            },
        )
        .expect("the graph has a single-dependency edge on an earlier root");

    eprintln!("binding edge {o} <- {d}; non-binding edge {o2} <- {d2}");
    let original = solve(PROBLEM).schedule();
    eprintln!(
        "original schedule: {d} at {}, {o} at {}",
        position(&original, &d),
        position(&original, &o)
    );
    assert!(position(&original, &d) < position(&original, &o));

    let mutated_text = drop_edge(PROBLEM, &o, &d);
    assert!(!depends_on_facts(&mutated_text)
        .get(&o)
        .is_some_and(|deps| deps.contains(&d)));
    let mutated = solve(&mutated_text);
    let mutated_schedule = mutated.schedule();
    assert_ne!(
        original, mutated_schedule,
        "dropping binding edge {o} <- {d} must change the policy"
    );
    eprintln!(
        "mutated schedule: {o} at {}, {d} at {}",
        position(&mutated_schedule, &o),
        position(&mutated_schedule, &d)
    );
    assert!(
        position(&mutated_schedule, &o) < position(&mutated_schedule, &d),
        "freed of {d}, {o} must now run before it"
    );
    let report = validate_fond_policy(&adapt_problem(mutated.flat.clone()), &mutated.plan);
    assert_eq!(report.guarantee, PolicyGuarantee::StrongCyclic);

    let control = solve(&drop_edge(PROBLEM, &o2, &d2)).schedule();
    assert_eq!(
        original, control,
        "dropping non-binding edge {o2} <- {d2} must leave the schedule unchanged"
    );
}
